CREATE OR REPLACE FUNCTION public.sgp_linea_plan_programar(p_token text, p_key_produccion text, p_fecha date, p_turno integer, p_cantidad integer, p_prioridad integer DEFAULT 50)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_user text;v_p public.sgp_producciones%rowtype;v_total integer;v_id uuid;
begin
 v_user:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR']);
 if p_fecha is null or p_turno is null or p_turno not in (1,2) or p_cantidad is null or p_cantidad<=0 or p_prioridad is null or p_prioridad<=0 then raise exception 'PARAMETROS_INVALIDOS';end if;
 select * into v_p from public.sgp_producciones where key_produccion=p_key_produccion and activa='SI' for update;
 if not found then raise exception 'PRODUCCION_NO_ENCONTRADA';end if;
 if coalesce(v_p.saldos_inicializados,false)=false or v_p.saldo_ensamble is null or v_p.saldo_ensamble<0 then raise exception 'SALDO_EXPORT_NO_VALIDADO';end if;
 select coalesce(sum(cantidad),0)::integer into v_total from public.sgp_linea_plan_asignaciones where key_produccion=p_key_produccion and estado<>'CANCELADA';
 if v_total+p_cantidad>v_p.saldo_ensamble then raise exception 'CANTIDAD_SUPERA_SALDO_EXPORT';end if;
 insert into public.sgp_linea_plan_asignaciones(key_produccion,fecha,turno,cantidad,prioridad,creado_por) values(p_key_produccion,p_fecha,p_turno,p_cantidad,p_prioridad,v_user) returning id into v_id;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_linea_plan_registrar(p_token text, p_asignacion uuid, p_cantidad integer, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_user text;v_a public.sgp_linea_plan_asignaciones%rowtype;v_total integer;v_remaining integer;
begin
 v_user:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER']);
 if p_cantidad is null or p_cantidad<=0 then raise exception 'CANTIDAD_INVALIDA';end if;
 select * into v_a from public.sgp_linea_plan_asignaciones where id=p_asignacion for update;
 if not found or v_a.estado in ('CANCELADA','FINALIZADA') then raise exception 'ASIGNACION_NO_DISPONIBLE';end if;
 select coalesce(sum(cantidad),0)::integer into v_total from public.sgp_linea_plan_ejecuciones where asignacion_id=p_asignacion;
 if v_total+p_cantidad>v_a.cantidad then raise exception 'EJECUCION_SUPERA_PROGRAMADO';end if;
 v_remaining:=v_a.cantidad-v_total-p_cantidad;
 if v_remaining>0 and nullif(trim(coalesce(p_observacion,'')),'') is null then raise exception 'OBSERVACION_OBLIGATORIA';end if;
 insert into public.sgp_linea_plan_ejecuciones(asignacion_id,cantidad,observacion,usuario) values(p_asignacion,p_cantidad,p_observacion,v_user);
 update public.sgp_linea_plan_asignaciones set estado=case when v_remaining=0 then 'FINALIZADA' else 'ABIERTA' end,actualizado_en=now() where id=p_asignacion;
 return jsonb_build_object('ejecutado',v_total+p_cantidad,'pendiente',v_remaining);
end $function$

CREATE OR REPLACE FUNCTION public.sgp_linea_plan_mover(p_token text, p_asignacion uuid, p_fecha date, p_turno integer, p_cantidad integer, p_prioridad integer DEFAULT 50)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_user text;v_a public.sgp_linea_plan_asignaciones%rowtype;v_ejecutado integer;v_id uuid;
begin
 v_user:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR']);
 if p_fecha is null or p_turno is null or p_turno not in(1,2) or p_cantidad is null or p_cantidad<=0 or p_prioridad is null or p_prioridad<=0 then raise exception 'PARAMETROS_INVALIDOS';end if;
 select * into v_a from public.sgp_linea_plan_asignaciones where id=p_asignacion for update;
 if not found or v_a.estado<>'PROGRAMADA' then raise exception 'ASIGNACION_NO_MOVIBLE';end if;
 select coalesce(sum(cantidad),0)::integer into v_ejecutado from public.sgp_linea_plan_ejecuciones where asignacion_id=p_asignacion;
 if v_ejecutado>0 or p_cantidad>v_a.cantidad then raise exception 'CANTIDAD_NO_DISPONIBLE';end if;
 if p_cantidad=v_a.cantidad then
 update public.sgp_linea_plan_asignaciones set fecha=p_fecha,turno=p_turno,prioridad=p_prioridad,actualizado_en=now() where id=p_asignacion;return p_asignacion;
 end if;
 update public.sgp_linea_plan_asignaciones set cantidad=cantidad-p_cantidad,actualizado_en=now() where id=p_asignacion;
 insert into public.sgp_linea_plan_asignaciones(key_produccion,fecha,turno,cantidad,prioridad,origen_id,creado_por)
 values(v_a.key_produccion,p_fecha,p_turno,p_cantidad,p_prioridad,p_asignacion,v_user) returning id into v_id;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_linea_plan_arrastrar(p_token text, p_asignacion uuid, p_fecha date, p_turno integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_user text;v_a public.sgp_linea_plan_asignaciones%rowtype;v_ejecutado integer;v_pendiente integer;v_id uuid;v_dest timestamp;v_orig timestamp;
begin
 v_user:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR']);
 if p_fecha is null or p_turno is null or p_turno not in(1,2) then raise exception 'PARAMETROS_INVALIDOS';end if;
 select * into v_a from public.sgp_linea_plan_asignaciones where id=p_asignacion for update;
 if not found or v_a.estado in('CANCELADA','FINALIZADA') then raise exception 'ASIGNACION_NO_DISPONIBLE';end if;
 v_orig:=v_a.fecha::timestamp+case when v_a.turno=1 then interval '7 hours' else interval '19 hours' end;
 v_dest:=p_fecha::timestamp+case when p_turno=1 then interval '7 hours' else interval '19 hours' end;
 if v_dest<=v_orig then raise exception 'DESTINO_NO_POSTERIOR';end if;
 if exists(select 1 from public.sgp_linea_plan_asignaciones where origen_id=p_asignacion and estado<>'CANCELADA') then raise exception 'ARRASTRE_YA_REALIZADO';end if;
 select coalesce(sum(cantidad),0)::integer into v_ejecutado from public.sgp_linea_plan_ejecuciones where asignacion_id=p_asignacion;
 v_pendiente:=v_a.cantidad-v_ejecutado;
 if v_pendiente<=0 then raise exception 'SIN_PENDIENTES';end if;
 update public.sgp_linea_plan_asignaciones set estado='FINALIZADA',observacion=concat_ws(' · ',observacion,'No culminado en turno: '||v_pendiente||' unidades trasladadas'),actualizado_en=now() where id=p_asignacion;
 insert into public.sgp_linea_plan_asignaciones(key_produccion,fecha,turno,cantidad,prioridad,origen_id,creado_por)
 values(v_a.key_produccion,p_fecha,p_turno,v_pendiente,1,p_asignacion,v_user) returning id into v_id;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_linea_plan_explorador_v327(p_token text, p_semana integer, p_linea text DEFAULT 'PANELES_2'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 perform public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER','LIDER MECANIZADO','CONSULTA']);
 if p_semana is null or p_semana not between 1 and 53 then raise exception 'SEMANA_INVALIDA'; end if;
 if p_linea not in ('PANELES_2','FRAMES_2') then raise exception 'LINEA_INVALIDA'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('key_produccion',p.key_produccion,'parte',d.parte,'vidrio_preparado',v.vidrio_preparado,'vidrio_novedad',v.vidrio_novedad,'vidrio_traslado',v.vidrio_traslado))
 from public.sgp_producciones p
 left join public.sgp_vidrio_resumen_produccion v on v.key_produccion=p.key_produccion
 left join lateral (select case when count(distinct nullif(trim(x.prioridad_semanal_snapshot),''))=1 then max(nullif(trim(x.prioridad_semanal_snapshot),'')) end parte from public.sgp_mecanizado_programacion_detalle x where x.key_produccion=p.key_produccion) d on true
 where p.id_linea=p_linea and p.activa='SI' and coalesce(p.semana_actual,p.semana_base)=p_semana),'[]'::jsonb);
end $function$
